package com.oms.order.service;

import com.oms.common.api.OrderStockClient;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;

/** Shared issue lifecycle. Domain sync cannot resolve another domain's issues. */
@Service
public class OrderIssueService {
    @Resource private OrderRepository repository;
    @Resource private OrderStockClient inventory;
    @Resource private OrderShipmentReceiptReviewService receiptReviews;
    public OrderIssueService(){}
    public OrderIssueService(OrderRepository repository){this.repository=repository;}
    private TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    private String marks(int n){return String.join(",",Collections.nCopies(n,"?"));}
    public void attach(String company,List<Map<String,Object>> orders){
        if(orders.isEmpty())return;List<Object> args=new ArrayList<>();args.add(company);for(Map<String,Object> order:orders)args.add(order.get("id"));Map<Long,List<Map<String,Object>>> byOrder=new HashMap<>();
        for(Map<String,Object> issue:repository.db().query("SELECT id,order_id,domain,category,reason_code,scope,stage,sku_sn,severity,blocking,state,message,first_seen,last_seen FROM oms_order_issue WHERE company_code=? AND order_id IN ("+marks(orders.size())+") AND state<>'RESOLVED' ORDER BY blocking DESC,id",ROW,args.toArray()))byOrder.computeIfAbsent(number(issue,"order_id"),k->new ArrayList<>()).add(issue);
        for(Map<String,Object> order:orders){List<Map<String,Object>> issues=byOrder.getOrDefault(number(order,"id"),Collections.emptyList());order.put("issues",issues);order.put("issue_count",issues.size());order.put("issue_sku_count",issues.stream().map(i->text(i,"sku_sn")).filter(s->!s.isEmpty()).distinct().count());}
    }
    public Map<String,Object> report(String company,long id){
        List<Map<String,Object>> heads=repository.db().query("SELECT id,order_sn,issue_synced_at,issue_sync_error FROM oms_order WHERE company_code=? AND id=?",ROW,company,id);require(heads.size()==1,"订单不存在或无权访问");Map<String,Object> report=heads.get(0);
        List<Map<String,Object>> issues=repository.db().query("SELECT * FROM oms_order_issue WHERE company_code=? AND order_id=? ORDER BY state='RESOLVED',blocking DESC,id DESC",ROW,company,id);for(Map<String,Object> issue:issues){try{issue.put("evidence",JSON.readValue(text(issue,"evidence_json"),Map.class));}catch(Exception e){issue.put("evidence_error","问题依据无法解析，请核对记录");}issue.remove("evidence_json");issue.remove("evidence_hash");issue.remove("issue_key");}report.put("issues",issues);
        List<Map<String,Object>> events=repository.db().query("SELECT id,issue_id,action,actor,message,evidence_json,create_time FROM oms_order_issue_event WHERE company_code=? AND order_id=? ORDER BY id DESC LIMIT 200",ROW,company,id);for(Map<String,Object> event:events){try{event.put("evidence",JSON.readValue(text(event,"evidence_json"),Map.class));}catch(Exception e){event.put("evidence_error","历史依据无法解析");}event.remove("evidence_json");}report.put("events",events);if(receiptReviews!=null)receiptReviews.attachOrders(company,Collections.singletonList(report));return report;
    }
    private void event(String company,long order,long issue,String action,String actor,String message,String json){repository.db().update("INSERT INTO oms_order_issue_event(company_code,order_id,issue_id,action,actor,message,evidence_json) VALUES (?,?,?,?,?,?,?)",company,order,issue,action,actor,message,json);}
    public void acknowledge(String company,long order,long id,String note,String actor){require(note!=null&&!note.trim().isEmpty()&&note.length()<=500,"请填写1至500字确认说明");tx().execute(status->{require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order WHERE company_code=? AND id=?",Long.class,company,order)==1,"订单不存在或无权访问");List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_order_issue WHERE company_code=? AND order_id=? AND id=? FOR UPDATE",ROW,company,order,id);require(rows.size()==1,"问题不存在或无权访问");Map<String,Object> issue=rows.get(0);require(!"RESOLVED".equals(text(issue,"state")),"问题已解除，无需确认");if("ACKNOWLEDGED".equals(text(issue,"state")))return null;repository.db().update("UPDATE oms_order_issue SET state='ACKNOWLEDGED',acknowledged_by=?,acknowledged_at=NOW(),acknowledgement=? WHERE company_code=? AND id=?",actor,note.trim(),company,id);event(company,order,id,"ACKNOWLEDGED",actor,note.trim(),text(issue,"evidence_json"));return null;});}
    @SuppressWarnings("unchecked") public void sync(String company,Map<String,Object> expected,Map<String,Object> facts){
        long id=number(expected,"id");tx().execute(status->{Map<String,Object> order=repository.db().query("SELECT * FROM oms_order WHERE company_code=? AND id=? FOR UPDATE",ROW,company,id).get(0);require(number(order,"control_version")==number(expected,"control_version"),"订单状态已变化，稍后重新核对");require(number(order,"channel_id")==number(facts,"channel_id")&&text(order,"platform_tid").equals(text(facts,"platform_tid")),"库存问题核对身份不一致");
            List<Map<String,Object>> ownedLines=repository.db().query("SELECT platform_oid,sku_sn,quantity,reserved_quantity FROM oms_order_line WHERE company_code=? AND order_id=?",ROW,company,id);require(facts.get("lines") instanceof List&&facts.get("sku_facts") instanceof List,"库存问题核对数据缺失");Map<String,Map<String,Object>> byOid=new HashMap<>();for(Map<String,Object> line:(List<Map<String,Object>>)facts.get("lines"))require(byOid.put(text(line,"platform_oid"),line)==null,"库存需求重复");require(byOid.size()==ownedLines.size(),"库存需求记录不完整，未清空原问题");for(Map<String,Object> line:ownedLines){Map<String,Object> fact=byOid.get(text(line,"platform_oid"));require(fact!=null&&text(fact,"sku_sn").equals(text(line,"sku_sn"))&&number(fact,"demand_quantity")==number(line,"quantity")&&(Arrays.asList("VOIDING","VOIDED").contains(text(order,"status"))||number(fact,"reserved_quantity")==number(line,"reserved_quantity")),"库存需求与订单尚未一致，稍后重新核对");}
            List<Map<String,Object>> desired=new ArrayList<>();long locked=0,publicQty=0;for(Map<String,Object> sku:(List<Map<String,Object>>)facts.get("sku_facts")){Map<String,Object> evidence=(Map<String,Object>)sku.get("evidence");locked+=number(evidence,"locked_reserved");publicQty+=number(evidence,"public_reserved");if(!Arrays.asList("VOIDING","VOIDED").contains(text(order,"status")))desired.addAll((List<Map<String,Object>>)sku.get("issues"));}
            if(!Arrays.asList("VOIDING","VOIDED").contains(text(order,"status"))&&"PART".equals(text(order,"allocation_status"))){long demand=ownedLines.stream().mapToLong(l->number(l,"quantity")).sum(),pending=Math.max(0,demand-number(order,"allocation_quantity"));if(pending>0){Map<String,Object> issue=new LinkedHashMap<>();issue.put("domain","INVENTORY");issue.put("category","SHORTAGE");issue.put("reason_code","WAREHOUSE_ALLOCATION_SHORTAGE");issue.put("scope","WAREHOUSE");issue.put("stage","ALLOCATE");issue.put("sku_sn","");issue.put("blocking",0);issue.put("severity","WARNING");issue.put("message","允许仓与当前分仓规则下尚有 "+pending+" 件未分仓，已分仓部分可继续履约");Map<String,Object> evidence=new LinkedHashMap<>();evidence.put("basis","ALLOCATION_RESULT");evidence.put("pending_allocation",pending);issue.put("evidence",evidence);desired.add(issue);}}
            reconcileDomain(company,id,"INVENTORY",desired);
            repository.db().update("UPDATE oms_order SET issue_synced_at=NOW(),issue_sync_error='',locked_reserved_quantity=?,public_reserved_quantity=? WHERE company_code=? AND id=?",locked,publicQty,company,id);return null;
        });
    }
    void reconcileDomain(String company,long order,String domain,List<Map<String,Object>> desired){
        Map<String,Map<String,Object>> previous=new HashMap<>();for(Map<String,Object> row:repository.db().query("SELECT * FROM oms_order_issue WHERE company_code=? AND order_id=? AND domain=? FOR UPDATE",ROW,company,order,domain))previous.put(text(row,"issue_key"),row);Set<String> seen=new HashSet<>();
        for(Map<String,Object> row:desired){require(domain.equals(text(row,"domain")),"问题域不一致");String key=hash(encode(Arrays.asList(text(row,"reason_code"),text(row,"scope"),text(row,"stage"),text(row,"sku_sn"))));require(seen.add(key),"重复问题");String json=encode(row.get("evidence")),digest=hash(json);Map<String,Object> old=previous.get(key);long id;
            if(old==null){repository.db().update("INSERT INTO oms_order_issue(company_code,order_id,domain,issue_key,category,reason_code,scope,stage,sku_sn,severity,blocking,message,evidence_json,evidence_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",company,order,domain,key,row.get("category"),row.get("reason_code"),row.get("scope"),row.get("stage"),row.get("sku_sn"),row.get("severity"),row.get("blocking"),row.get("message"),json,digest);id=repository.db().queryForObject("SELECT id FROM oms_order_issue WHERE company_code=? AND order_id=? AND domain=? AND issue_key=?",Long.class,company,order,domain,key);event(company,order,id,"OPENED",("INVENTORY".equals(domain)?"库存核对任务":"平台回传任务"),text(row,"message"),json);}
            else{id=number(old,"id");boolean reopened="RESOLVED".equals(text(old,"state")),changed=!digest.equals(text(old,"evidence_hash"))||number(old,"blocking")!=number(row,"blocking")||!text(old,"message").equals(text(row,"message"));boolean material=number(old,"blocking")!=number(row,"blocking")||!text(old,"message").equals(text(row,"message"));String state=reopened||material?"OPEN":text(old,"state");repository.db().update("UPDATE oms_order_issue SET category=?,severity=?,blocking=?,state=?,message=?,evidence_json=?,evidence_hash=?,last_seen=NOW(),resolved_at=NULL,acknowledged_by=IF(?,'',acknowledged_by),acknowledged_at=IF(?,NULL,acknowledged_at),acknowledgement=IF(?,'',acknowledgement) WHERE company_code=? AND id=?",row.get("category"),row.get("severity"),row.get("blocking"),state,row.get("message"),json,digest,reopened||material,reopened||material,reopened||material,company,id);if(reopened||changed)event(company,order,id,reopened?"REOPENED":"CHANGED",("INVENTORY".equals(domain)?"库存核对任务":"平台回传任务"),text(row,"message"),json);}
        }
        for(Map<String,Object> old:previous.values())if(!seen.contains(text(old,"issue_key"))&&!"RESOLVED".equals(text(old,"state"))){repository.db().update("UPDATE oms_order_issue SET state='RESOLVED',resolved_at=NOW(),last_seen=NOW() WHERE company_code=? AND id=?",company,old.get("id"));event(company,order,number(old,"id"),"RESOLVED",("INVENTORY".equals(domain)?"库存核对任务":"平台回传任务"),"当前核对已无该问题，原发生依据保留",text(old,"evidence_json"));}
    }
    public Map<String,Object> recheck(String company,long id){List<Map<String,Object>> rows=repository.db().query("SELECT id,channel_id,platform_tid,control_version FROM oms_order WHERE company_code=? AND id=?",ROW,company,id);require(rows.size()==1,"订单不存在或无权访问");List<Map<String,Object>> facts=data(inventory.diagnostics(company,rows,SecurityConstants.INNER));require(facts.size()==1,"库存核对返回范围不完整");sync(company,rows.get(0),facts.get(0));return report(company,id);}
    private final Map<String,Long> cursors=new HashMap<>();
    public Map<String,Object> pollCompany(String company){
        com.oms.common.task.ScanReport report=new com.oms.common.task.ScanReport();
        String cursorKey=String.valueOf(com.baomidou.dynamic.datasource.toolkit.DynamicDataSourceContextHolder.peek())+"/"+company;long cursor=cursors.getOrDefault(cursorKey,0L);String where=" WHERE o.company_code=? AND ((o.status NOT IN ('VOIDING','VOIDED') AND EXISTS(SELECT 1 FROM oms_order_line l WHERE l.company_code=o.company_code AND l.order_id=o.id AND l.quantity>COALESCE((SELECT SUM(sl.shipped_quantity) FROM oms_order_shipment_line sl WHERE sl.company_code=l.company_code AND sl.order_line_id=l.id),0))) OR EXISTS(SELECT 1 FROM oms_order_issue i WHERE i.company_code=o.company_code AND i.order_id=o.id AND i.state<>'RESOLVED'))";
        List<Map<String,Object>> orders=repository.db().query("SELECT o.id,o.channel_id,o.platform_tid,o.control_version"+" FROM oms_order o"+where+" AND o.id>? ORDER BY o.id LIMIT 50",ROW,company,cursor);if(orders.isEmpty()&&cursor>0)orders=repository.db().query("SELECT o.id,o.channel_id,o.platform_tid,o.control_version FROM oms_order o"+where+" ORDER BY o.id LIMIT 50",ROW,company);if(orders.isEmpty()){cursors.put(cursorKey,0L);return report;}cursors.put(cursorKey,number(orders.get(orders.size()-1),"id"));
        try{List<Map<String,Object>> facts=data(inventory.diagnostics(company,orders,SecurityConstants.INNER));require(facts.size()==orders.size(),"库存核对返回范围不完整");Map<String,Map<String,Object>> lookup=new HashMap<>();for(Map<String,Object> fact:facts)require(lookup.put(number(fact,"channel_id")+"/"+text(fact,"platform_tid"),fact)==null,"库存核对返回重复订单");for(Map<String,Object> order:orders)try{Map<String,Object> fact=lookup.get(number(order,"channel_id")+"/"+text(order,"platform_tid"));require(fact!=null,"库存核对返回缺失");sync(company,order,fact);report.record(company,number(order,"id"),"","SUCCESS","本次库存问题核对完成");}catch(RuntimeException e){report.record(company,number(order,"id"),"","FAILED","库存问题核对暂未完成，原问题保留");repository.db().update("UPDATE oms_order SET issue_sync_error='库存问题核对暂未完成，请稍后刷新；原问题保留' WHERE company_code=? AND id=?",company,order.get("id"));}}
        catch(RuntimeException e){report.scopeFailure(company);for(Map<String,Object> order:orders)repository.db().update("UPDATE oms_order SET issue_sync_error='库存问题服务暂未确认，请稍后刷新；原问题保留' WHERE company_code=? AND id=?",company,order.get("id"));}
        return report;
    }
}
